def switch_endian(n, bits):
    if n < 0 or bits < 8 or bits & (bits - 1) != 0:
        return None

    num_bytes = bits // 8
    if n.bit_length() > bits:
        return None

    result = 0
    for i in range(num_bytes):
        byte = (n >> (i * 8)) & 0xFF
        result |= byte << ((num_bytes - 1 - i) * 8)

    return result
