def find_middle(string):
    import re

    # Check if input is a string
    if not isinstance(string, str):
        return -1

    # Find all digits in the string
    digits = re.findall(r'\d', string)

    # If no digits found, return -1
    if not digits:
        return -1

    # Calculate the product of the digits
    product = 1
    for digit in digits:
        product *= int(digit)

    # Convert the product to a string to find the middle digits
    product_str = str(product)

    # If the product is a single digit, return it as an integer
    if len(product_str) == 1:
        return int(product_str)

    # If the product has an even number of digits, return the middle two digits
    if len(product_str) % 2 == 0:
        mid_index = len(product_str) // 2
        return int(product_str[mid_index - 1:mid_index + 1])

    # If the product has an odd number of digits, return the middle digit
    mid_index = len(product_str) // 2
    return int(product_str[mid_index])
