def wheat_from_chaff(values):
    n = len(values)
    chaff = []
    wheat = []

    # Separate negative and positive numbers
    for value in values:
        if value < 0:
            chaff.append(value)
        else:
            wheat.append(value)

    # Find the position to insert the first positive number
    pos_index = next((i for i, v in enumerate(values) if v >= 0), n)

    # Replace misplaced positive numbers with the last negative number
    for i in range(pos_index, n):
        if values[i] >= 0:
            values[i] = chaff.pop()
        else:
            wheat.append(values[i])

    # Insert the remaining negative numbers at the beginning
    values[:len(chaff)] = chaff

    return values
