        '5': '五', '6': '六', '7': '七', '8': '八', '9': '九'
    }

    # Mapping of place multipliers to Chinese characters
    place_multipliers = {
        '0': '', '1': '十', '2': '百', '3': '千', '4': '万'
    }

    # Handle negative numbers
    if n < 0:
        return '负' + to_chinese_numeral(-n)

